// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Ask the AI service for edits to a template
	// (POST /ai/template-edits)
	SuggestTemplateEdits(w http.ResponseWriter, r *http.Request)
	// List the compose history
	// (GET /builds)
	ListBuilds(w http.ResponseWriter, r *http.Request)
	// Start an image build
	// (POST /builds)
	StartBuild(w http.ResponseWriter, r *http.Request)
	// List a build's output artifacts
	// (GET /builds/{id}/artifacts)
	ListBuildArtifacts(w http.ResponseWriter, r *http.Request, id BuildId)
	// Cancel a running build
	// (POST /builds/{id}/cancel)
	CancelBuild(w http.ResponseWriter, r *http.Request, id BuildId)
	// Get a build's command, resolved paths, and summary
	// (GET /builds/{id}/details)
	GetBuildDetails(w http.ResponseWriter, r *http.Request, id BuildId)
	// Get the Edge Pack capability grouping
	// (GET /edge-pack)
	GetEdgePack(w http.ResponseWriter, r *http.Request, params GetEdgePackParams)
	// Get the full configuration manifest
	// (GET /manifest)
	GetManifest(w http.ResponseWriter, r *http.Request)
	// List available package repositories
	// (GET /package-repos)
	ListPackageRepos(w http.ResponseWriter, r *http.Request, params ListPackageReposParams)
	// Search available packages
	// (GET /packages/search)
	SearchPackages(w http.ResponseWriter, r *http.Request, params SearchPackagesParams)
	// Get what the current user may do
	// (GET /session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// Resolve the base template for a set of selections
	// (POST /templates/compose)
	ComposeTemplate(w http.ResponseWriter, r *http.Request)
	// Validate an edited template
	// (POST /templates/validate)
	ValidateTemplate(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// SuggestTemplateEdits operation middleware
func (siw *ServerInterfaceWrapper) SuggestTemplateEdits(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.SuggestTemplateEdits(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// ListBuilds operation middleware
func (siw *ServerInterfaceWrapper) ListBuilds(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.ListBuilds(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

// StartBuild operation middleware
